// STAKEHOLDER_GROUPS: Update with actual recipient email addresses or distribution lists for each role.
// Replace placeholder addresses before activating this workflow.
const STAKEHOLDER_GROUPS = [
  { role: 'Demand Planner', email: 'demand.planners@example.com', detail_level: 'full' },
  { role: 'Category Manager', email: 'category.managers@example.com', detail_level: 'summary' },
  { role: 'Supply Chain Analyst', email: 'sc.analysts@example.com', detail_level: 'full' },
  { role: 'Store Manager', email: 'store.managers@example.com', detail_level: 'headline' }
];

const body = $('Classification Notification Received').first().json.body;

return STAKEHOLDER_GROUPS.map(group => ({
  json: {
    role: group.role,
    email: group.email,
    detail_level: group.detail_level,
    run_id: body.run_id,
    run_date: body.run_date,
    total_classified: body.total_classified,
    seasonal_count: body.seasonal_count,
    low_confidence_count: body.low_confidence_count,
    dashboard_url: body.dashboard_url,
    top_seasonal_articles: body.top_seasonal_articles || []
  }
}));

const items = $input.all();
const results = items[0]?.json?.notification_results || [];
const runId = $('Classification Notification Received').first().json.body.run_id || 'unknown';
const notifiedCount = results.filter(r => r.success === true).length;

return [{
  json: {
    run_id: runId,
    notified_count: notifiedCount,
    total_groups: results.length,
    status: 'completed'
  }
}];
